import type { TraceTerminalSpec, Point } from "../trace.layout";
import { traceSideOf } from "../trace.layout";
import type {
  ElbowPin,
  ElbowRect,
  ElbowRoute,
  ElbowRouteInput,
  ElbowRouteOptions,
  ElbowRoutingObstacle,
} from "./index";

export interface TraceElbowRequest {
  from: TraceTerminalSpec;
  to: TraceTerminalSpec;
  /** Keep-outs the route must not cross. A story fixture IS this list —
   * there is no obstacle COLLECTOR here, by design (the donor's
   * `routingObstacles.ts` reads live tldraw shapes and stayed behind). */
  obstacles?: readonly ElbowRoutingObstacle[];
  /** The owning card's box, when a terminal sits on one. Endpoint boxes get
   * the router's special treatment: the first/last leg may cross its own
   * card while leaving through the port, but no later segment may re-enter. */
  fromBox?: ElbowRect | null;
  toBox?: ElbowRect | null;
  pins?: readonly ElbowPin[];
  options?: Partial<ElbowRouteOptions>;
}

/**
 * `{x, y, dir}` pairs -> the router's `ElbowRouteInput`.
 *
 * The only interesting line is the side derivation, and it is NOT symmetric:
 * a wire LEAVES the `from` terminal along the flow, and ARRIVES at the `to`
 * terminal travelling `to.dir` — so the free space at the `to` end is BEHIND
 * it, which is `OPPOSITE_DIR[to.dir]`. Getting this backwards produces routes
 * that look plausible in the classic left-to-right case (where the two happen
 * to coincide) and loop absurdly for every other tangent, which is exactly
 * why the rule was frozen in the plan rather than re-derived per lane.
 */
export function elbowInputFromTerminals(request: TraceElbowRequest): ElbowRouteInput {
  const { from, to, obstacles, fromBox, toBox, pins, options } = request;
  return {
    start: { point: { x: from.x, y: from.y }, side: traceSideOf(from, "from"), box: fromBox ?? null },
    end: { point: { x: to.x, y: to.y }, side: traceSideOf(to, "to"), box: toBox ?? null },
    ...(obstacles ? { obstacles } : {}),
    ...(pins ? { pins } : {}),
    ...(options ? { options } : {}),
  };
}

/** The route's vertices as this app's `Point[]` — what `TraceBody`'s `points`
 * prop and `TraceBadge`'s drag math both take. A structural copy, so a caller
 * mutating it cannot reach back into a route. */
export function routePoints(route: ElbowRoute): Point[] {
  return route.points.map((point) => ({ x: point.x, y: point.y }));
}

// src/components/trace.bends.ts — ADDED, no donor as code. The MODEL is the
// donor's own `elbow/elbowPins.ts` (PORTED VERBATIM there, read at
// `./elbow/elbowPins.ts`, itself from SystemSketch): a dragged control point
// stores a normalized scalar pair in the frame spanned by the two endpoints,
// never an absolute `{x, y}`, so it survives the endpoints moving instead of
// stranding itself in space. See that file's own "Why not Excalidraw's
// `fixedSegments`" for the general argument against absolute points; D1 of
// docs/TRACE-CONTROL-POINTS-PLAN.md is that argument applied to a straight
// chord's `(t, o)` — a fraction ALONG the chord and an offset PERPENDICULAR
// to it — instead of `ElbowPin`'s axis-aligned `(index, axis, t, offset)`,
// because a `straight` route has one segment to bend, not N axis-aligned
// rails.
//
// Pure geometry, no React, no DOM — this is where the round-trip is
// unit-tested (`trace.bends.test.ts`).

import type { Point } from "./trace.layout";

/**
 * One intermediate control point on a `straight` trace, stored in the
 * chord's own frame so it survives the endpoints moving.
 *
 * `t` — fraction along start→end (may leave 0..1; a bend is allowed to sit
 *       "behind" the start, which is how a hairpin is drawn).
 * `o` — perpendicular offset from the chord in px, positive to the LEFT of
 *       the direction of travel.
 */
export interface TraceBend {
  t: number;
  o: number;
}

/**
 * Below this chord length the frame has no direction to build `(t, o)` from
 * — `start` and `end` are the same point, or close enough that floating
 * point noise would dominate the unit vector. D1's fallback: use the screen
 * axes instead of throwing, so both conversions below stay TOTAL functions
 * over every `start`/`end` pair, degenerate ones included.
 */
const DEGENERATE_CHORD_EPS = 1e-6;

/**
 * `(t, o)` → the absolute point it names, given the chord's current
 * endpoints.
 *
 * The chord's unit tangent is `u = (end - start) / |end - start|`. "Left of
 * the direction of travel" in SCREEN space (y grows down) is `u` rotated
 * -90°, i.e. `p = (u.y, -u.x)` — walking along `u = (1, 0)` (rightward on
 * screen), `p = (0, -1)` is "up", which is where a left hand points when
 * facing right on a page. The point is then `start + t * length * u + o * p`.
 */
export function traceBendPoint(bend: TraceBend, start: Point, end: Point): Point {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const length = Math.hypot(dx, dy);
  if (length < DEGENERATE_CHORD_EPS) {
    // No direction to build a frame from. Fall back to the screen axes — t
    // along +x, o along −y — so the conversion stays total (D1).
    return { x: start.x + bend.t, y: start.y - bend.o };
  }
  const ux = dx / length;
  const uy = dy / length;
  const px = uy;
  const py = -ux;
  return {
    x: start.x + ux * bend.t * length + px * bend.o,
    y: start.y + uy * bend.t * length + py * bend.o,
  };
}

/**
 * The inverse of {@link traceBendPoint}: an absolute point → the `(t, o)`
 * that names it in the CURRENT chord's frame. Because `u`/`p` above are
 * orthonormal, `t * length = (point - start) · u` and `o = (point - start)
 * · p` — a plain projection, and `traceBendFrom(traceBendPoint(bend, s, e),
 * s, e)` round-trips `bend` exactly (modulo float error).
 */
export function traceBendFrom(point: Point, start: Point, end: Point): TraceBend {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const length = Math.hypot(dx, dy);
  const relX = point.x - start.x;
  const relY = point.y - start.y;
  if (length < DEGENERATE_CHORD_EPS) {
    return { t: relX, o: -relY };
  }
  const ux = dx / length;
  const uy = dy / length;
  const px = uy;
  const py = -ux;
  return {
    t: (relX * ux + relY * uy) / length,
    o: relX * px + relY * py,
  };
}

// src/components/trace.handles.ts — ADDED, no donor as code. The MODEL is
// the donor's `virtual`/`vertex` + `grow:` idea, read-only at
// /home/bam/systemsketch rev 10748b8c
// (`src/blocks/connections/ConnectionShapeUtil.tsx:556-631`, `getHandles`):
// two terminals plus a `virtual` handle sitting on the midpoint of every
// segment until dragged, at which point it "grows" into a real vertex. D3
// of docs/TRACE-CONTROL-POINTS-PLAN.md is that idea over this repo's own
// `TraceBend` polyline instead of a tldraw shape's segments.
//
// WHAT CHANGED, exhaustively: there is no `TLHandle`, no `IndexKey`, no
// pill/delay handle (that is a different concern, not this plan's). The
// donor gates an END segment's grow handle on `ELBOW_END_HANDLE_MIN_LENGTH`
// so a stubby leg does not overlap the port dot; the same reason, restated
// here as `minVirtualSegmentPx`, gates EVERY segment (not just the ends) —
// a straight trace has no fixed "end leg" the way an authored elbow route
// does, so the guard has to apply uniformly.
//
// Pure function, no React, no DOM — this is where the derivation is
// unit-tested (`trace.handles.test.ts`); `traceEditor.tsx` is the only
// caller that mounts it.

import type { Point } from "./trace.layout";

export type TraceHandleKind = "terminal" | "bend" | "virtual";

export interface TraceHandle {
  /** `"start"` | `"end"` | `bend:${i}` | `virtual:${i}`. */
  id: string;
  kind: TraceHandleKind;
  x: number;
  y: number;
  /** bend: its index in `bends`. virtual: the index a NEW bend would take
   * (dragging it inserts at exactly this position in the `bends` array —
   * see `trace.routing.ts`'s `TraceRouteOptions.bends` doc for the
   * array-order contract this matches). */
  index: number;
}

/** Donor's `ELBOW_END_HANDLE_MIN_LENGTH` reason, restated: "a stubby end
 * segment leaves no room between the port and the first corner; a handle
 * there would overlap the port dot." */
const DEFAULT_MIN_VIRTUAL_SEGMENT_PX = 24;

/**
 * Given the resolved polyline `[start, ...bends, end]`, the handles a
 * `straight` trace's editor should offer: a `terminal` at each end, a
 * `bend` at every interior vertex, and a `virtual` at the midpoint of every
 * segment long enough to hold one.
 */
export function traceHandles(
  points: readonly Point[],
  options: { minVirtualSegmentPx?: number } = {},
): TraceHandle[] {
  const minVirtualSegmentPx = options.minVirtualSegmentPx ?? DEFAULT_MIN_VIRTUAL_SEGMENT_PX;
  if (points.length < 2) return [];

  const handles: TraceHandle[] = [
    { id: "start", kind: "terminal", x: points[0].x, y: points[0].y, index: 0 },
  ];

  for (let i = 1; i < points.length - 1; i += 1) {
    handles.push({ id: `bend:${i - 1}`, kind: "bend", x: points[i].x, y: points[i].y, index: i - 1 });
  }

  const last = points[points.length - 1];
  handles.push({ id: "end", kind: "terminal", x: last.x, y: last.y, index: 0 });

  for (let i = 0; i < points.length - 1; i += 1) {
    const a = points[i];
    const b = points[i + 1];
    const segmentLength = Math.hypot(b.x - a.x, b.y - a.y);
    if (segmentLength < minVirtualSegmentPx) continue;
    handles.push({
      id: `virtual:${i}`,
      kind: "virtual",
      x: (a.x + b.x) / 2,
      y: (a.y + b.y) / 2,
      index: i,
    });
  }

  return handles;
}

